package com.fintrack.khmtomnenh.order.service; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.order.dto.OrderDto; import com.fintrack.khmtomnenh.order.entity.Order; import com.fintrack.khmtomnenh.order.repository.OrderRepository; import com.fintrack.khmtomnenh.orderitem.entity.OrderItem; import com.fintrack.khmtomnenh.quotation.entity.Quotation; import com.fintrack.khmtomnenh.quotation.service.QuotationService; import lombok.RequiredArgsConstructor; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class OrderService {private final OrderRepository repo;private final QuotationService quotations;public List<Order> mine(Auth a){return a.getRole().name().equals("BUYER")?repo.findByBuyerIdOrderByCreatedAtDesc(a.getId()):repo.findBySupplierIdOrderByCreatedAtDesc(a.getId());}public Order get(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found"));}@Transactional public Order accept(Long quotationId,Auth buyer){Quotation q=quotations.get(quotationId);quotations.assertBuyer(q,buyer);if(repo.existsByQuotationId(q.getId()))throw new IllegalArgumentException("Quotation already accepted");q.setStatus("ACCEPTED");q.getRfq().setStatus("AWARDED");Order o=Order.builder().buyer(buyer).supplier(q.getSupplier()).quotation(q).totalAmount(q.getTotalAmount()).status("PENDING").build();for(var x:q.getItems())o.getItems().add(OrderItem.builder().order(o).product(x.getProduct()).quantity(x.getQuantity()).unitPrice(x.getUnitPrice()).build());return repo.save(o);}@Transactional public Order updateStatus(Long id,OrderDto d,Auth a){Order o=get(id);boolean buyer=o.getBuyer().getId().equals(a.getId()),supplier=o.getSupplier().getId().equals(a.getId());if(!buyer&&!supplier)throw new AccessDeniedException("Not order participant");String st=d.status().trim().toUpperCase();Set<String> allowed=Set.of("PENDING","CONFIRMED","PROCESSING","SHIPPED","DELIVERED","CANCELLED");if(!allowed.contains(st))throw new IllegalArgumentException("Invalid order status");if("CANCELLED".equals(st)&&!buyer&&!supplier)throw new AccessDeniedException("Not authorized");o.setStatus(st);return o;}}
